import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_k11s4p2_nchw_fp32(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 pN,
    .param .u32 pC,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pKout,
    .param .u32 pK,
    .param .u32 pOH,
    .param .u32 pOW,
    .param .u32 pStride,
    .param .u32 pPad,
    .param .u32 pTotal
)
{
    .reg .pred  p_exit, p_tmp, p_ge0, p_ltH, p_ltW, p_ih_ok, p_iw_ok, p_loop_kw, p_loop_kh, p_loop_ic;
    .reg .b32   r_idx, r_tot, rN, rC, rH, rW, rKout, rK, rOH, rOW, rStride, rPad;
    .reg .b32   r_mul1, r_mul2, r_kowow, r_ohow;
    .reg .b32   r_n, r_rem1, r_oc, r_rem2, r_oh, r_ow;
    .reg .b32   r_ic, r_kh, r_kw;
    .reg .b32   r_tmp0, r_tmp1, r_tmp2, r_tmp3, r_in_index, r_w_index, r_out_index;
    .reg .b32   rH_u, rW_u;
    .reg .s32   rs_ih_base, rs_iw_base, rs_ih, rs_iw, rs_oh, rs_ow, rs_stride, rs_pad, rs_H, rs_W;
    .reg .f32   f_acc, f_in, f_w;
    .reg .b64   rd_in, rd_w, rd_b, rd_out, rd_addr, rd_off;

    // Load params
    ld.param.u64 rd_in,   [in_ptr];
    ld.param.u64 rd_w,    [w_ptr];
    ld.param.u64 rd_b,    [b_ptr];
    ld.param.u64 rd_out,  [out_ptr];

    ld.param.u32 rN,      [pN];
    ld.param.u32 rC,      [pC];
    ld.param.u32 rH,      [pH];
    ld.param.u32 rW,      [pW];
    ld.param.u32 rKout,   [pKout];
    ld.param.u32 rK,      [pK];
    ld.param.u32 rOH,     [pOH];
    ld.param.u32 rOW,     [pOW];
    ld.param.u32 rStride, [pStride];
    ld.param.u32 rPad,    [pPad];
    ld.param.u32 r_tot,   [pTotal];

    // Compute linear thread index
    .reg .b32 r_cta, r_ntid, r_tid;
    mov.u32 r_cta, %ctaid.x;
    mov.u32 r_ntid, %ntid.x;
    mov.u32 r_tid, %tid.x;
    mad.lo.u32 r_idx, r_cta, r_ntid, r_tid;

    // Bounds check for total elements
    setp.ge.u32 p_exit, r_idx, r_tot;
    @p_exit bra END;

    // Precompute denominators
    mul.lo.u32 r_mul1, rKout, rOH;        // Kout * OH
    mul.lo.u32 r_kowow, r_mul1, rOW;      // Kout * OH * OW
    mul.lo.u32 r_ohow, rOH, rOW;          // OH * OW

    // Decompose linear index into (n, oc, oh, ow)
    div.u32 r_n,    r_idx,  r_kowow;
    rem.u32 r_rem1, r_idx,  r_kowow;

    div.u32 r_oc,   r_rem1, r_ohow;
    rem.u32 r_rem2, r_rem1, r_ohow;

    div.u32 r_oh,   r_rem2, rOW;
    rem.u32 r_ow,   r_rem2, rOW;

    // Base indices for input computation
    cvt.s32.u32 rs_oh, r_oh;
    cvt.s32.u32 rs_ow, r_ow;
    cvt.s32.u32 rs_stride, rStride;
    cvt.s32.u32 rs_pad, rPad;
    mul.lo.s32 rs_ih_base, rs_oh, rs_stride;
    sub.s32    rs_ih_base, rs_ih_base, rs_pad;
    mul.lo.s32 rs_iw_base, rs_ow, rs_stride;
    sub.s32    rs_iw_base, rs_iw_base, rs_pad;

    // Prepare H, W as signed for comparisons
    cvt.s32.u32 rs_H, rH;
    cvt.s32.u32 rs_W, rW;

    // Load bias: f_acc = bias[oc]
    {
        .reg .b64 rd_off_b;
        cvt.u64.u32 rd_off_b, r_oc;
        shl.b64 rd_off_b, rd_off_b, 2;
        add.s64 rd_addr, rd_b, rd_off_b;
        ld.global.f32 f_acc, [rd_addr];
    }

    // Loop over input channels ic
    mov.u32 r_ic, 0;
IC_LOOP:
    setp.ge.u32 p_tmp, r_ic, rC;
    @p_tmp bra IC_DONE;

    // Loop over kernel height kh
    mov.u32 r_kh, 0;
KH_LOOP:
    setp.ge.u32 p_tmp, r_kh, rK;
    @p_tmp bra KH_DONE;

    // Compute ih and check bounds
    cvt.s32.u32 rs_ih, r_kh;
    add.s32 rs_ih, rs_ih_base, rs_ih;
    setp.ge.s32 p_ge0, rs_ih, 0;
    setp.lt.s32 p_ltH, rs_ih, rs_H;
    and.pred p_ih_ok, p_ge0, p_ltH;
    @!p_ih_ok bra KH_NEXT;

    // Loop over kernel width kw
    mov.u32 r_kw, 0;
KW_LOOP:
    setp.ge.u32 p_tmp, r_kw, rK;
    @p_tmp bra KW_DONE;

    // Compute iw and check bounds
    cvt.s32.u32 rs_iw, r_kw;
    add.s32 rs_iw, rs_iw_base, rs_iw;
    setp.ge.s32 p_ge0, rs_iw, 0;
    setp.lt.s32 p_ltW, rs_iw, rs_W;
    and.pred p_iw_ok, p_ge0, p_ltW;
    @!p_iw_ok bra KW_NEXT;

    // Compute input index: (((n*C + ic)*H + ih)*W + iw)
    mul.lo.u32 r_tmp0, r_n, rC;                 // n*C
    add.u32    r_tmp0, r_tmp0, r_ic;            // n*C + ic
    mul.lo.u32 r_tmp1, r_tmp0, rH;              // *H
    cvt.u32.s32 r_tmp2, rs_ih;                  // ih (non-negative here)
    add.u32    r_tmp1, r_tmp1, r_tmp2;          // + ih
    mul.lo.u32 r_tmp2, r_tmp1, rW;              // *W
    cvt.u32.s32 r_tmp3, rs_iw;                  // iw (non-negative here)
    add.u32    r_in_index, r_tmp2, r_tmp3;      // + iw

    // Compute weight index: (((oc*C + ic)*K + kh)*K + kw)
    mul.lo.u32 r_tmp0, r_oc, rC;                // oc*C
    add.u32    r_tmp0, r_tmp0, r_ic;            // + ic
    mul.lo.u32 r_tmp1, r_tmp0, rK;              // *K
    add.u32    r_tmp1, r_tmp1, r_kh;            // + kh
    mul.lo.u32 r_tmp2, r_tmp1, rK;              // *K
    add.u32    r_w_index, r_tmp2, r_kw;         // + kw

    // Load input and weight, accumulate
    {
        .reg .b64 rd_in_off, rd_w_off;
        cvt.u64.u32 rd_in_off, r_in_index;
        shl.b64 rd_in_off, rd_in_off, 2;
        add.s64 rd_addr, rd_in, rd_in_off;
        ld.global.f32 f_in, [rd_addr];
        cvt.u64.u32 rd_w_off, r_w_index;
        shl.b64 rd_w_off, rd_w_off, 2;
        add.s64 rd_addr, rd_w, rd_w_off;
        ld.global.f32 f_w, [rd_addr];
        fma.rn.f32 f_acc, f_in, f_w, f_acc;
    }

KW_NEXT:
    add.u32 r_kw, r_kw, 1;
    setp.lt.u32 p_loop_kw, r_kw, rK;
    @p_loop_kw bra KW_LOOP;

KW_DONE:
    // Next kh
KH_NEXT:
    add.u32 r_kh, r_kh, 1;
    setp.lt.u32 p_loop_kh, r_kh, rK;
    @p_loop_kh bra KH_LOOP;

KH_DONE:
    // Next ic
    add.u32 r_ic, r_ic, 1;
    bra IC_LOOP;

IC_DONE:
    // Compute output index: (((n*Kout + oc)*OH + oh)*OW + ow)
    mul.lo.u32 r_tmp0, r_n, rKout;          // n*Kout
    add.u32    r_tmp0, r_tmp0, r_oc;        // + oc
    mul.lo.u32 r_tmp1, r_tmp0, rOH;         // *OH
    add.u32    r_tmp1, r_tmp1, r_oh;        // + oh
    mul.lo.u32 r_tmp2, r_tmp1, rOW;         // *OW
    add.u32    r_out_index, r_tmp2, r_ow;   // + ow

    // Store output
    {
        .reg .b64 rd_out_off;
        cvt.u64.u32 rd_out_off, r_out_index;
        shl.b64 rd_out_off, rd_out_off, 2;
        add.s64 rd_addr, rd_out, rd_out_off;
        st.global.f32 [rd_addr], f_acc;
    }

END:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_k11s4p2_nchw_fp32")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        # Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2
        # Parameters
        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size))
        self.bias = nn.Parameter(torch.empty(self.out_channels))
        # PyTorch Conv2d default init: kaiming_uniform_(a=sqrt(5)) => uniform(-1/sqrt(fan_in), 1/sqrt(fan_in))
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1.0 / math.sqrt(fan_in)
        with torch.no_grad():
            self.weight.uniform_(-bound, bound)
            self.bias.uniform_(-bound, bound)

    def forward(self, x: torch.Tensor):
        # Shapes
        N, C, H, W = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        OC = self.out_channels
        # Output dimensions (PyTorch conv2d formula for dilation=1)
        OH = (H + 2 * P - K) // S + 1
        OW = (W + 2 * P - K) // S + 1

        # Allocate output tensor
        y = torch.empty((N, OC, OH, OW), device=x.device, dtype=x.dtype)

        # Ensure contiguous inputs
        x_c = x.contiguous()
        w_c = self.weight.contiguous()
        b_c = self.bias.contiguous()

        # Launch PTX kernel
        total = N * OC * OH * OW
        block = 256
        grid = ( (total + block - 1) // block, 1, 1 )

        module = _get_ptx_module()
        module.launch(
            "conv2d_k11s4p2_nchw_fp32",
            grid=grid,
            block=(block, 1, 1),
            arguments=[
                x_c, w_c, b_c, y,
                i32(N), i32(C), i32(H), i32(W),
                i32(OC), i32(K), i32(OH), i32(OW),
                i32(S), i32(P), i32(total)
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

